insert into pb_ai.eval_runs(run, fn, label, k, ids, cases) select '1121-lib7f-check', 'ai-next', 'lib7f: check the v7d fixes (r9 + 148 fails + guards)', (o - 1)::int, array(select x->>'id' from jsonb_array_elements(e) x), e from jsonb_array_elements($j$[[{"id":"st7-01","q":"At what depth do I need shoring or a trench box?","where":"Spokane, WA","level":"pipelayer"},{"id":"st7-06","q":"What is the minimum wage I have to pay a new laborer?","where":"Savannah, GA","level":"office"},{"id":"st7-08","q":"At what depth do I need shoring or a trench box?","where":"Phoenix, AZ","level":"pipelayer"}],[{"id":"st7-11","q":"At what depth do I need shoring or a trench box?","where":"Oakland, CA","level":"pipelayer"}]]$j$::jsonb) with ordinality t(e, o);
insert into pb_ai.eval_runs(run, fn, label, k, ids, cases) with s as (select *, (row_number() over (order by id) - 1) / 3 g from pb_ai.eval_set where id = any(array['lib-in-dig-3','lib-or-sp-6','lib-wa-sp-13','lib-la-dig-3','lib-wv-dig-3','lib-il-dig-4','sa10','sw1','tr12','tr14','nw12','cs1']))
  select '1121-lib7f-check', 'ai-next', 'lib7f: check the v7d fixes (r9 + 148 fails + guards)', 1000 + g, array_agg(id), jsonb_agg(jsonb_build_object('id', id, 'q', q, 'where', "where", 'level', level)
      || case when images is null then '{}'::jsonb else jsonb_build_object('images', images) end
      || case when image_ids is null then '{}'::jsonb else jsonb_build_object('image_ids', to_jsonb(image_ids)) end
      || case when feature is null then '{}'::jsonb else jsonb_build_object('feature', feature) end
      || case when model is null then '{}'::jsonb else jsonb_build_object('model', model) end) from s group by g;
select pb_ai.eval_pump('1121-lib7f-check') started, (select count(*) from pb_ai.eval_runs where run = '1121-lib7f-check') batches;
